import { useState, useEffect } from 'react';
import axios from 'axios';

const RegistrationForm = () => {
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');

  // Установка CSRF-токена в заголовки запросов
  useEffect(() => {
    const csrfTokenElement = document.querySelector('meta[name="csrf-token"]');
    if (csrfTokenElement) {
      const csrfToken = csrfTokenElement.getAttribute('content');
      axios.defaults.headers.common['X-CSRF-TOKEN'] = csrfToken;
    }
  }, []);

  const handleSubmit = async (event) => {
    event.preventDefault();

    try {
      const response = await axios.post('http://127.0.0.1:8000/register', {
        name, email, password
      });

      if (response.data.success === true) {
        alert("Регистрация прошла успешно!");
      } else {
        alert(response.data.message || "Возникла проблема при регистрации.");
      }
    } catch (error) {
      if (error.response && error.response.data) {
        alert(error.response.data.message || "Ошибка регистрации");
      } else {
        alert("Что-то пошло не так при попытке зарегистрироваться. Проверьте подключение к Интернету.");
      }
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      <input placeholder='Имя' value={name} onChange={(e) => setName(e.target.value)} className="input-field" /><br/>
      <input placeholder='Email' value={email} onChange={(e) => setEmail(e.target.value)} className="input-field" /><br/>
      <input type='password' placeholder='Пароль' value={password} onChange={(e) => setPassword(e.target.value)} className="input-field" /><br/>
      <button type='submit' className="btn-submit">Зарегистрироваться</button>
    </form>
  );
};

export default RegistrationForm;
